// Post-process the auto-generated API MDX files so the operation description
// is rendered INSIDE the APIPage component (left column of the 2-col layout)
// instead of as full-width MDX prose above it. Two changes per file:
//
//   1. Strip the description text between the generated-comment line and the
//      `<APIPage>` tag — fumadocs-openapi already keeps the same text in
//      frontmatter and will re-render it via the `description` slot.
//   2. Add `showDescription` to the `<APIPage>` tag so the slot is populated.
//
// Run with: node scripts/post-process-api-mdx.mjs
// Idempotent: safe to run repeatedly.

import { readFile, writeFile, readdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const apiDir = path.resolve(here, '../content/docs/api');

const SKIP_TOP_LEVEL = new Set([
  'index.mdx',
  'index.de.mdx',
  'authentication.mdx',
  'authentication.de.mdx',
  'errors.mdx',
  'errors.de.mdx',
  'pagination.mdx',
  'pagination.de.mdx',
]);

let touched = 0;

async function* walk(dir) {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      yield* walk(full);
    } else if (entry.isFile() && entry.name.endsWith('.mdx')) {
      yield full;
    }
  }
}

function transform(text) {
  // Frontmatter starts with `---\n` and ends with `\n---\n`. Find the closing
  // delimiter, which is the first `\n---` after position 0.
  if (!text.startsWith('---')) return text;
  const fmCloseIdx = text.indexOf('\n---', 3);
  if (fmCloseIdx < 0) return text;
  const headEnd = fmCloseIdx + 4; // past the `\n---`
  // Include trailing newline if present.
  const cut = text[headEnd] === '\n' ? headEnd + 1 : headEnd;
  const head = text.slice(0, cut);
  let body = text.slice(cut);

  // Locate the APIPage tag — bail out if absent (hand-written page).
  const apiTagMatch = body.match(/<APIPage\b[^>]*\/>/);
  if (!apiTagMatch) return text;

  // Locate the generated-comment line that fumadocs-openapi inserts.
  const commentRe = /\{\/\*[^*]*generated by Fumadocs[^*]*\*\/\}\s*\n/;
  const commentMatch = body.match(commentRe);
  if (!commentMatch) return text;
  const afterComment =
    commentMatch.index + commentMatch[0].length;
  const apiTagStart = body.indexOf(apiTagMatch[0], afterComment);

  // Drop everything between the comment and the APIPage tag (the duplicated
  // description prose). Keep one blank line for readability.
  let rebuilt =
    body.slice(0, afterComment) +
    '\n' +
    body.slice(apiTagStart);

  // Add `showDescription` if not already there.
  rebuilt = rebuilt.replace(
    /<APIPage\b(?![^>]*\bshowDescription\b)/,
    '<APIPage showDescription',
  );

  return head + rebuilt;
}

for await (const file of walk(apiDir)) {
  // Skip hand-written narrative pages at api/ root.
  if (path.dirname(file) === apiDir && SKIP_TOP_LEVEL.has(path.basename(file))) {
    continue;
  }
  const before = await readFile(file, 'utf8');
  const after = transform(before);
  if (after !== before) {
    await writeFile(file, after);
    touched++;
  }
}

console.log(`Post-processed ${touched} API MDX file(s).`);
